from fractions import Fraction as F
from itertools import combinations,combinations_with_replacement
from pathlib import Path
import ast,hashlib,json,resource,sys,time

resource.setrlimit(resource.RLIMIT_CPU,(40,41))
resource.setrlimit(resource.RLIMIT_AS,(1024**3,1024**3))
started=time.monotonic();ROOT=Path.cwd();N=37
pairs=list(combinations(range(4),2));triples=list(combinations(range(4),3))
unknowns=['sigma','r','t']+['c'+str(i) for i in range(6)]+['l'+str(i) for i in range(24)]
def term(a,*inds):
    e=[0]*N
    for i in inds:e[i]+=1
    return {tuple(e):F(a)} if a else {}
def add(*ps):
    out={}
    for p in ps:
        for e,a in p.items():out[e]=out.get(e,F(0))+a
    return {e:a for e,a in out.items() if a}
def scale(p,a):return {e:a*b for e,b in p.items() if a*b}
def mul(p,q):
    out={}
    for e,a in p.items():
        for f,b in q.items():
            m=tuple(x+y for x,y in zip(e,f));out[m]=out.get(m,F(0))+a*b
    return {e:a for e,a in out.items() if a}
def der(p,i):
    out={}
    for e,a in p.items():
        if e[i]:
            m=list(e);m[i]-=1;out[tuple(m)]=a*e[i]
    return out
def tensor(data):
    out={}
    for (i,j),p in data.items():out[i,j]=p;out[j,i]=scale(p,-1)
    return out
def jacobi(P):
    return [add(*(mul(P.get((a,l),{}),der(P.get((b,c),{}),l))
             for a,b,c in [(i,j,k),(j,k,i),(k,i,j)] for l in range(4))) for i,j,k in triples]
def pf(P):return add(mul(P[0,1],P[2,3]),scale(mul(P[0,2],P[1,3]),-1),mul(P[0,3],P[1,2]))
def divergence(P):return [add(*(der(P.get((i,j),{}),i) for i in range(4))) for j in range(4)]
def invariant(P,Z):
    return [add(*(mul(Z[k],der(P[i,j],k)) for k in range(4)),
                *(scale(mul(P.get((k,j),{}),der(Z[i],k)),-1) for k in range(4)),
                *(scale(mul(P.get((i,k),{}),der(Z[j],k)),-1) for k in range(4))) for i,j in pairs]
def parse(text):
    names={**{'x'+str(i+1):i for i in range(4)},**{'n'+str(i):i+4 for i in range(9)}}
    def walk(n):
        if isinstance(n,ast.Constant) and isinstance(n.value,int):return term(n.value)
        if isinstance(n,ast.Name) and n.id in names:return term(1,names[n.id])
        if isinstance(n,ast.UnaryOp) and isinstance(n.op,ast.USub):return scale(walk(n.operand),-1)
        if isinstance(n,ast.BinOp):
            if isinstance(n.op,ast.Add):return add(walk(n.left),walk(n.right))
            if isinstance(n.op,ast.Sub):return add(walk(n.left),scale(walk(n.right),-1))
            if isinstance(n.op,ast.Mult):return mul(walk(n.left),walk(n.right))
            if isinstance(n.op,ast.Div) and isinstance(n.right,ast.Constant):return scale(walk(n.left),F(1,n.right.value))
            if isinstance(n.op,ast.Pow) and isinstance(n.right,ast.Constant):
                p=term(1)
                for _ in range(n.right.value):p=mul(p,walk(n.left))
                return p
        raise ValueError(ast.dump(n))
    return walk(ast.parse(text,mode='eval').body)
def substitute(p,replacements):
    out={}
    for e,a in p.items():
        m=list(e)
        for j in replacements:m[j]=0
        value={tuple(m):a}
        for j,q in replacements.items():
            for _ in range(e[j]):value=mul(value,q)
        out=add(out,value)
    return out
def source_substitute(P,replacements):return tensor({ij:substitute(P[ij],replacements) for ij in pairs})
def coefficient_polys(polynomials):
    out=[]
    for p in polynomials:
        coeff={}
        for e,a in p.items():
            mon=e[:4];m=(0,)*4+e[4:]
            coeff[mon]=add(coeff.get(mon,{}),{m:a})
        out.extend((mon,coef) for mon,coef in sorted(coeff.items()) if coef)
    return out
def rref(A):
    B=[[F(v) for v in row] for row in A];rank=0;pivots=[]
    if not B:return B,pivots
    for j in range(len(B[0])):
        k=next((i for i in range(rank,len(B)) if B[i][j]),None)
        if k is None:continue
        B[k],B[rank]=B[rank],B[k];a=B[rank][j];B[rank]=[v/a for v in B[rank]]
        for i in range(len(B)):
            a=B[i][j]
            if i!=rank and a:B[i]=[x-a*y for x,y in zip(B[i],B[rank])]
        pivots.append(j);rank+=1
    return B,pivots
def same_span(ps,qs):
    mons=sorted(set().union(*(set(p) for p in ps+qs)))
    A,ap=rref([[p.get(m,F(0)) for m in mons] for p in ps])
    B,bp=rref([[p.get(m,F(0)) for m in mons] for p in qs])
    assert len(ap)==len(bp) and A[:len(ap)]==B[:len(bp)]
    return len(ap)

X=[term(1,1),term(1,2),term(1,3),{}]
Y=[add(term(F(-1,4),0),term(F(7,4),4,0),term(1,5,2),term(1,6,3)),
   add(term(F(-1,4),1),term(F(3,4),4,1),term(1,5,3)),
   add(term(F(-1,4),2),term(F(-1,4),4,2)),
   add(term(F(-1,4),3),term(F(-5,4),4,3))]
Q=tensor({(i,j):add(mul(X[i],Y[j]),scale(mul(Y[i],X[j]),-1)) for i,j in pairs})
assert not pf(Q)
assert divergence(Q)==X
P=tensor({ij:add(Q[ij],term(1,7+k),*(term(1,13+4*k+i,i) for i in range(4))) for k,ij in enumerate(pairs)})
input_path='reports/CLASSIFICATION_MULTIPLE_HYPERPLANE_NILPOTENT_20261107.json'
input_report=json.loads((ROOT/input_path).read_text())
chart_results=[];sources=[]
space_monomials=[]
for degree in range(3):
    for factors in combinations_with_replacement(range(4),degree):
        e=[0]*4
        for i in factors:e[i]+=1
        space_monomials.append(tuple(e))
for gamma,record in enumerate(input_report['charts']):
    assert record['gamma']==gamma
    Z=X[:];Z[3]=term(gamma)
    equations=invariant(P,Z)+[add(a,scale(b,-1)) for a,b in zip(divergence(P),Z)]
    A=[];rhs=[]
    for equation in equations:
        rows={e:[F(0)]*34 for e in space_monomials}
        for e,c in equation.items():
            assert sum(e[4:])<=1 and e[:4] in rows
            if sum(e[4:])==0:rows[e[:4]][33]+=c
            else:
                j=next(i for i,v in enumerate(e[4:]) if v);rows[e[:4]][j]+=c
        for e in space_monomials:A.append(rows[e][:33]);rhs.append(-rows[e][33])
    reduced,pivots=rref(A)
    sub={i+4:parse(record['full_source_substitution'][name]) for i,name in enumerate(unknowns)}
    assert all(not substitute(equation,sub) for equation in equations)
    nr=record['free_parameter_count'];direction_matrix=[]
    for i in range(33):
        direction_matrix.append([sub[i+4].get(tuple(int(k==j+4) for k in range(N)),F(0)) for j in range(nr)])
    _,image_pivots=rref(direction_matrix)
    assert len(image_pivots)==nr and len(pivots)==33-nr
    Pn=source_substitute(P,sub);assert all(Pn[ij]==parse(expr) for ij,expr in zip(pairs,record['all_six_brackets']))
    J=jacobi(Pn);assert J==[parse(p) for p in record['all_four_jacobi_polynomials']]
    Factual=pf(Pn);assert Factual==parse(record['actual_affine_pfaffian'])
    assert divergence(Pn)==Z and all(not p for p in invariant(Pn,Z))
    sources.append(Pn)
    chart_results.append({'gamma':gamma,'all_coefficient_matrix_shape':[len(A),33],
        'linear_rank_QQ':len(pivots),'full_affine_solution_dimension':nr,'substitution_image_rank_QQ':len(image_pivots),
        'source_is_full_affine_solution':True,'all_six_brackets_match':True,'all_four_Jacobi_polynomials_match':True,
        'actual_Pfaffian_matches':True,'full_divergence_and_modular_invariance':True,
        'constraint_matrix_sha256':hashlib.sha256(json.dumps([[str(a) for a in row] for row in A]).encode()).hexdigest()})

six_strings=['n3*(3*n7-1)','n2*(7*n7-1)','n1*(n7-1)+4*n3**2',
             '8*n2*n6+12*n3*n8+(1-15*n7)*n4','(15*n7-3)*n0-12*n1*n6+8*n2**2+12*n3*n5','n1*n2']
six=[parse(f) for f in six_strings]
rank=same_span([p for _,p in coefficient_polys(jacobi(sources[0]))],six);assert rank==6

P1=sources[1];successive={};triangular=[]
for name,target in [('n2','-n4'),('n1','0'),('n5','0'),('n0','0')]:
    index=4+int(name[1:]);desired=add(term(1,index),scale(parse(target),-1))
    coeffs=coefficient_polys(jacobi(source_substitute(P1,successive)))
    found=None
    for mon,p in coeffs:
        key=next(iter(desired));ratio=p.get(key,F(0))/desired[key]
        if ratio and p==scale(desired,ratio):found=(mon,ratio);break
    assert found is not None
    triangular.append({'forced_equation':name+'-('+target+')','coefficient_monomial':list(found[0]),'coefficient_ratio':str(found[1])})
    successive[index]=parse(target)
P1final=source_substitute(P1,successive)
assert all(not p for p in jacobi(P1final)) and not pf(P1final)

branches={
 's_1_3':({'n7':'1/3','n1':'6*n3**2','n2':'0','n4':'3*n3*n8','n0':'36*n3**2*n6-6*n3*n5'},'n3',(1,0,0,2),'-n3'),
 's_1_7':({'n7':'1/7','n3':'0','n1':'0','n4':'7*n2*n6','n0':'28*n2**2/3'},'n2',(0,1,0,2),'-2*n2/3'),
 's_1':({'n7':'1','n2':'0','n3':'0','n4':'0','n0':'n1*n6'},'n1',(0,0,0,0),'-n1**2'),
 's_1_5':({'n7':'1/5','n1':'0','n2':'0','n3':'0','n4':'0'},'n0',(0,0,0,2),'-n0/2'),
 's_1_15':({'n7':'1/15','n0':'0','n1':'0','n2':'0','n3':'0'},'n4',(0,0,0,3),'-n4/3'),
}
branch_results={}
for name,(mapping,nonzero,mon,witness) in branches.items():
    sub={4+int(k[1:]):parse(v) for k,v in mapping.items()}
    Pb=source_substitute(sources[0],sub)
    assert all(not p for p in jacobi(Pb))
    Factual=pf(Pb);coeff=dict(coefficient_polys([Factual]))[mon]
    assert coeff==parse(witness)
    assert not substitute(Factual,{4+int(nonzero[1:]):{}})
    free=sorted({j-4 for p in Pb.values() for e in p for j in range(4,13) if e[j]})
    assert len(free)==4
    branch_results[name]={'substitution':mapping,'rank4_iff_nonzero':nonzero,'free_parameters':['n'+str(i) for i in free],
       'all_four_Jacobi_polynomials_zero':True,'rank4_witness_coordinate_monomial':list(mon),'rank4_witness_coefficient':witness,
       'Pfaffian_zero_on_excluded_boundary':True}
assert not pf(source_substitute(sources[0],{4+i:{} for i in range(5)}))
checker=Path(__file__).read_text()
result={'task_id':'E_multiple_hyperplane','all_passed':True,'field':'QQ',
 'method':'Independent Fraction sparse polynomial construction and exact rational linear elimination; no SymPy or producer import.',
 'independent_checker_source':checker,'source_sha256':hashlib.sha256(checker.encode()).hexdigest(),
 'input_sha256':{input_path:hashlib.sha256((ROOT/input_path).read_bytes()).hexdigest()},
 'all33_unknown_names':unknowns,'retained_low_coefficients':{'constant':6,'linear':24},
 'highest_normal_form_checks':{'decomposable_Pfaffian_zero':True,'divergence_equals_Jordan4_field':True},
 'charts':chart_results,'gamma0_all_Jacobi_equivalent_to_six_conditions':six_strings,
 'gamma1_successive_forced_equations':triangular,'gamma1_full_Pfaffian_zero_after_necessary_conditions':True,
 'five_complete_rank4_sources':branch_results,
 'exhaustiveness_case_split':['d!=0 forces s=1/3 and the first source','d=0,c!=0 forces s=1/7 and the second source',
  'd=c=0,b!=0 forces s=1 and the third source','d=c=b=0,a!=0 forces s=1/5,e=0 and the fourth source',
  'd=c=b=a=0,e!=0 forces s=1/15 and the fifth source','d=c=b=a=e=0 has identically zero Pfaffian'],
 'max_normal_source_dimension':4,
 'scope':'Exact full affine linear source elimination and exhaustive rank4 support in both supplied Jordan4 modular charts. The prior reduction of every rank3-nilpotent highest quadratic to this normal form, and the affine group/fixed-constant primitive-beta dimension argument, are separate geometric dependencies.',
 'global_exhaustion_proved':False,'elapsed_seconds':time.monotonic()-started}
output=Path(sys.argv[1]) if len(sys.argv)>1 else ROOT/'reports/CLASSIFICATION_MULTIPLE_HYPERPLANE_NILPOTENT_REVIEW_20261107.json'
with output.open('x') as stream:json.dump(result,stream,indent=2);stream.write('\n')
print(json.dumps({k:result[k] for k in ['all_passed','max_normal_source_dimension','gamma1_full_Pfaffian_zero_after_necessary_conditions','elapsed_seconds']},indent=2))
